/**
 * Writes the AIRIS permission guard as a real Pi extension.
 *
 * Pi discovers extensions as `*.ts` / `*.js` files inside
 * `<agentDir>/extensions` (extensions/loader.ts:833, isExtensionFile) and calls
 * a module's default export with the ExtensionAPI, so the guard is registered
 * through `pi.on("tool_call", ...)` and returns Pi's own
 * `ToolCallEventResult { block, reason }`.
 *
 * The generated file imports the guard implementation from this package so the
 * policy logic is not duplicated.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { AirisPermissionPolicy } from "./guard.ts";

export interface GuardExtensionOptions {
	/** Agent directory Pi uses for global config, e.g. ~/.airis/agent. */
	agentDir: string;
	/** AIRIS policy to enforce. Serialized into the extension. */
	policy: AirisPermissionPolicy;
	/** Absolute path of the JSONL audit file the extension appends to. */
	auditPath: string;
	/** Session id recorded in every audit entry (AIRIS AuditEntry.sessionId). */
	sessionId: string;
	/** Absolute path of this package's guard module (guard.ts). */
	guardModulePath: string;
}

/** Path the guard extension will occupy for a given agent directory. */
export function guardExtensionPath(agentDir: string): string {
	return join(agentDir, "extensions", "airis-guard.ts");
}

/**
 * Writes the guard extension and returns its path.
 * The file is regenerated on every call, so policy changes take effect on the
 * next session without touching Pi's own configuration.
 */
export function writeGuardExtension(options: GuardExtensionOptions): string {
	const target = guardExtensionPath(options.agentDir);
	mkdirSync(join(options.agentDir, "extensions"), { recursive: true });

	const guardImport = options.guardModulePath.replace(/\\/g, "/");
	const source = `// GENERATED by @sufiyan-sabeel/airis-runtime. Do not edit.
// Enforces AIRIS permissions on Pi tool calls and records every decision using
// AIRIS's own AuditEntry schema: { timestamp, type, sessionId, data }.
import { appendFileSync } from "node:fs";
import { createAirisGuard } from ${JSON.stringify(guardImport)};

const POLICY = ${JSON.stringify(options.policy)};
const AUDIT_PATH = ${JSON.stringify(options.auditPath)};
const SESSION_ID = ${JSON.stringify(options.sessionId)};

const write = (type, data) => {
	try {
		appendFileSync(
			AUDIT_PATH,
			JSON.stringify({ timestamp: new Date().toISOString(), type, sessionId: SESSION_ID, data }) + "\\n",
			"utf8",
		);
	} catch {
		// Audit failure must never allow a call through; the decision is returned
		// regardless and the guard itself still fails closed.
	}
};

const guard = createAirisGuard({
	policy: POLICY,
	audit: (record) => {
		write("tool_call", {
			tool: record.tool,
			decision: record.decision,
			reason: record.reason,
			target: record.target,
		});
	},
});

export default function airisGuard(pi) {
	pi.on("tool_call", (event) => {
		const decision = guard.onToolCall({
			tool: event.toolName,
			input: (event.input ?? {}),
		});
		if (decision.block) {
			return { block: true, reason: decision.reason ?? "blocked by AIRIS policy" };
		}
		return undefined;
	});

	pi.on("tool_result", (event) => {
		write("tool_result", { tool: event.toolName });
	});
}
`;
	writeFileSync(target, source, "utf8");
	return target;
}
